BEGIN;
CREATE TABLE IF NOT EXISTS forge_policy_documents(id text PRIMARY KEY,tenant_id text NOT NULL,name text NOT NULL,current_version integer NOT NULL CHECK(current_version>0),state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN('ACTIVE','DISABLED','REVOKED')),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS forge_policy_versions(id text PRIMARY KEY,policy_id text NOT NULL REFERENCES forge_policy_documents(id) ON DELETE RESTRICT,version integer NOT NULL CHECK(version>0),schema_version integer NOT NULL,document jsonb NOT NULL,canonical_hash text NOT NULL CHECK(canonical_hash~'^[a-f0-9]{64}$'),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(policy_id,version),UNIQUE(policy_id,canonical_hash));
CREATE TABLE IF NOT EXISTS forge_policy_bundles(id text PRIMARY KEY,tenant_id text NOT NULL,name text NOT NULL,priority integer NOT NULL DEFAULT 100,state text NOT NULL DEFAULT 'ACTIVE' CHECK(state IN('ACTIVE','DISABLED','REVOKED')),current_epoch bigint NOT NULL DEFAULT 0,active_versions jsonb NOT NULL DEFAULT '[]',rollout_percent integer NOT NULL DEFAULT 100 CHECK(rollout_percent BETWEEN 0 AND 100),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS forge_policy_activation_epochs(bundle_id text NOT NULL REFERENCES forge_policy_bundles(id) ON DELETE RESTRICT,tenant_id text NOT NULL,epoch bigint NOT NULL CHECK(epoch>0),versions jsonb NOT NULL,rollout_percent integer NOT NULL CHECK(rollout_percent BETWEEN 0 AND 100),previous_epoch bigint,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(bundle_id,epoch));
CREATE TABLE IF NOT EXISTS forge_policy_emergency_denies(id uuid PRIMARY KEY,tenant_id text NOT NULL,action text NOT NULL DEFAULT '*',resource_type text NOT NULL DEFAULT '*',reason text NOT NULL,expires_at timestamptz NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS forge_policy_decisions(id uuid PRIMARY KEY,tenant_id text NOT NULL,epoch bigint NOT NULL DEFAULT 0,subject jsonb NOT NULL,resource jsonb NOT NULL,action text NOT NULL,decision text NOT NULL CHECK(decision IN('ALLOW','DENY')),reason text NOT NULL,evidence jsonb NOT NULL,signature text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_policy_operator_audit(id uuid PRIMARY KEY,tenant_id text NOT NULL,actor text NOT NULL,action text NOT NULL,policy_id text,bundle_id text,version integer,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_policy_documents_tenant_idx ON forge_policy_documents(tenant_id,state);
CREATE INDEX IF NOT EXISTS forge_policy_versions_policy_idx ON forge_policy_versions(policy_id,version DESC);
CREATE INDEX IF NOT EXISTS forge_policy_bundles_tenant_idx ON forge_policy_bundles(tenant_id,state,priority DESC);
CREATE INDEX IF NOT EXISTS forge_policy_decisions_tenant_idx ON forge_policy_decisions(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS forge_policy_emergency_active_idx ON forge_policy_emergency_denies(tenant_id,action,resource_type,expires_at) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS forge_policy_operator_audit_tenant_idx ON forge_policy_operator_audit(tenant_id,created_at DESC);
COMMIT;
